// Package opts splits a tool's arguments into options and operands, the
// way GNU's getopt does for the options the tools know.
package opts

import (
	"fmt"
	"strings"
)

// Opt is one option as given: its short name and, for an option that
// takes one, its value.
type Opt struct {
	Name  byte
	Value string
}

// Spec is what a tool knows: its short options without a value, those
// with one, and its long options by the short name each stands for.
type Spec struct {
	Flags  string
	Valued string
	Long   map[string]byte
}

// Parse splits args into options, in the order given, and operands.
// Options may come anywhere before "--"; short ones may be clustered, and
// a valued one takes the rest of its cluster or the next argument. "-"
// alone is an operand. An option the tool does not know, or a value
// missing, is an error in GNU's words.
//
//charter:realizes SW-261126-2QDT
func Parse(args []string, spec Spec) ([]Opt, []string, error) {
	var opts []Opt
	var operands []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch {
		case a == "--":
			return opts, append(operands, args[i+1:]...), nil
		case strings.HasPrefix(a, "--"):
			name, value, hasValue := strings.Cut(a[2:], "=")
			short, ok := spec.Long[name]
			if !ok {
				return nil, nil, fmt.Errorf("unrecognized option '%s'", a)
			}
			if strings.IndexByte(spec.Valued, short) >= 0 {
				if !hasValue {
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("option '--%s' requires an argument", name)
					}
					i++
					value = args[i]
				}
			} else if hasValue {
				return nil, nil, fmt.Errorf("option '--%s' doesn't allow an argument", name)
			}
			opts = append(opts, Opt{Name: short, Value: value})
		case len(a) > 1 && a[0] == '-':
			for j := 1; j < len(a); j++ {
				c := a[j]
				switch {
				case strings.IndexByte(spec.Valued, c) >= 0:
					value := a[j+1:]
					if value == "" {
						if i+1 >= len(args) {
							return nil, nil, fmt.Errorf("option requires an argument -- '%c'", c)
						}
						i++
						value = args[i]
					}
					opts = append(opts, Opt{Name: c, Value: value})
					j = len(a)
				case strings.IndexByte(spec.Flags, c) >= 0:
					opts = append(opts, Opt{Name: c})
				default:
					return nil, nil, fmt.Errorf("invalid option -- '%c'", c)
				}
			}
		default:
			operands = append(operands, a)
		}
	}
	return opts, operands, nil
}
package opts

import (
	"fmt"
	"strings"
	"testing"

	"example.com/coreutils/claims"
	"github.com/leroux/charter/chartertest"
)

var spec = Spec{Flags: "lw", Valued: "df", Long: map[string]byte{"fields": 'f', "lines": 'l'}}

// parse renders what Parse made of args: the options, then the operands.
func parse(t *testing.T, args ...string) string {
	t.Helper()
	opts, operands, err := Parse(args, spec)
	if err != nil {
		t.Fatalf("Parse(%q): %v", args, err)
	}
	var b strings.Builder
	for _, o := range opts {
		fmt.Fprintf(&b, "-%c%s ", o.Name, o.Value)
	}
	return b.String() + "| " + strings.Join(operands, " ")
}

func TestClusteredOptions(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_2QDT, "clustered")
	if got := parse(t, "-lw", "f"); got != "-l -w | f" {
		t.Errorf("-lw f parsed as %q", got)
	}
}

func TestOptionsAfterOperands(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_2QDT, "after-operands")
	if got := parse(t, "a", "-l", "b"); got != "-l | a b" {
		t.Errorf("a -l b parsed as %q", got)
	}
}

func TestDoubleDashEndsOptions(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_2QDT, "double-dash")
	if got := parse(t, "-w", "--", "-l", "-"); got != "-w | -l -" {
		t.Errorf("-w -- -l - parsed as %q", got)
	}
}

func TestAValueAttachedOrNext(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_2QDT, "value-attached-or-next")
	a, b := parse(t, "-d:", "-f1"), parse(t, "-d", ":", "-f", "1")
	if a != "-d: -f1 | " || a != b {
		t.Errorf("-d: -f1 parsed as %q, -d : -f 1 as %q; want the same", a, b)
	}
}

func TestLongForms(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_2QDT, "long-forms")
	a, b := parse(t, "--fields=2"), parse(t, "--fields", "2")
	if a != "-f2 | " || b != a {
		t.Errorf("--fields=2 parsed as %q, --fields 2 as %q; want -f2", a, b)
	}
}

func TestAnUnknownOptionIsRefused(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_2QDT, "unknown-refused")
	for args, want := range map[string]string{
		"-lZ":   "invalid option -- 'Z'",
		"--bad": "unrecognized option '--bad'",
		"-d":    "option requires an argument -- 'd'",
	} {
		if _, _, err := Parse([]string{args}, spec); err == nil || err.Error() != want {
			t.Errorf("Parse(%s) error %v, want %q", args, err, want)
		}
	}
}
