func parseTab(prev int, v string) (int, error) {
	var t int
	switch {
	case v == "":
		return 0, fmt.Errorf("empty tab")
	case v == "\\\\0":
		t = 0
	case len(v) > 1:
		return 0, fmt.Errorf("multi-character tab '%s'", v)
	default:
		t = int(v[0])
	}
	if prev != noTab && prev != t {
		return 0, fmt.Errorf("incompatible tabs")
	}
	return t, nil
}
